(x, y, t) => {
  const cx = 240, cy = 120;
  const f1 = Math.sin(x*0.023+t*0.31)*12+Math.cos(y*0.019-t*0.22)*8;
  const f2 = Math.cos(x*0.017-t*0.27)*10+Math.sin(y*0.021+t*0.33)*9;
  const f3 = Math.sin((x+y)*0.012+t*0.18)*6;
  const sx = x+f1+f3, sy = y+f2+f3;
  const src = [
    [120+Math.sin(t*0.5)*90, 70+Math.cos(t*0.35)*50, 0.09, 2.1, 1.0],
    [360+Math.cos(t*0.45)*80, 90+Math.sin(t*0.6)*60, 0.11, 1.8, 0.8],
    [200+Math.sin(t*0.3+2)*120, 160+Math.cos(t*0.5+1)*70, 0.07, 2.4, 1.2],
    [80+Math.cos(t*0.7+1)*70, 180+Math.sin(t*0.55+3)*50, 0.13, 1.6, 0.9],
    [400+Math.sin(t*0.38+4)*80, 180+Math.cos(t*0.8+2)*60, 0.08, 2.7, 1.1],
    [240+Math.cos(t*0.32+5)*100, 220+Math.sin(t*0.48)*70, 0.1, 2.0, 0.7],
    [300+Math.sin(t*0.55+3)*60, 40+Math.cos(t*0.65+1)*40, 0.14, 1.4, 1.3],
    [160+Math.cos(t*0.42+2)*90, 130+Math.sin(t*0.58+4)*55, 0.065, 2.5, 0.85]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp), w2=Math.cos(d*f*0.8-t*sp*0.7+0.5);
    aS+=w1*w; aS2+=w2*w;
    iS+=Math.sin(d*f*0.6+t*sp*0.5+1.8)*w;
    iS2+=Math.cos(d*f*0.5-t*sp*0.4+2.2)*w;
  }
  const n=8;
  const act=aS/n, act2=aS2/n, inh=iS/n, inh2=iS2/n;
  const lapA = act2-act*0.3, lapI = inh2-inh*0.3;
  const react = act*act*inh*0.4 + act*inh*0.6 + lapA*1.5 - lapI*0.8;
  const bg = (Math.sin(sx*0.035+sy*0.028+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2
    + Math.sin((sx+sy)*0.1+t*2.2)*0.15 + Math.sin((sx-sy)*0.08-t*1.8)*0.15
    + Math.sin(sx*0.06+sy*0.04+t*1.5)*Math.cos(sx*0.04-sy*0.05-t*1.2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35;
  const spiral2=Math.sin(dist*0.025-ang*2-t*0.7)*Math.cos(dist*0.03+ang*5+t*0.9)*0.2;
  const micro=Math.sin(sx*0.22+t*1.8)*Math.sin(sy*0.22-t*1.5)*Math.cos((sx-sy)*0.15+t*0.8)*0.15;
  const combined = react + bg*0.25 + spiral + spiral2 + micro;
  const rd = Math.tanh(combined*1.8);
  const cell = Math.tanh((Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx+sy)*0.08+t)*0.4)*1.2)*0.25;
  const edge = Math.abs(rd)>0.65?Math.abs(rd):Math.abs(rd)*0.6;
  const glow = Math.exp(-Math.abs(rd)*2)*0.3;
  const blend = rd*0.6 + cell*0.2 + edge*0.15 + glow*0.05;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,85],[18,90,115],[25,140,135],[45,175,145],
    [120,195,120],[195,195,70],[215,165,55],[225,125,60],[195,75,55],
    [155,45,60],[100,25,55],[50,15,50],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const smooth=f*f*(3-2*f);
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*smooth;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth;
  const lum=0.85+Math.sin(rd*Math.PI*1.2)*0.15+glow*0.3;
  const hiEdge=Math.abs(rd)>0.75?1.2+Math.abs(rd)*0.15:1.0;
  const satBoost=1+Math.abs(rd)*0.15;
  const gray=(r0+g0+b0)/3;
  const fr=r0+(r0-gray)*satBoost, fg=g0+(g0-gray)*satBoost, fb=b0+(b0-gray)*satBoost;
  return [
    Math.min(255,(fr*lum*hiEdge)|0),
    Math.min(255,(fg*lum*hiEdge)|0),
    Math.min(255,(fb*lum*hiEdge)|0)
  ];
}
